import sys, json
sys.path.insert(0,'tools')
import sympy
from halffrob import _sym_to_t, _psi, _cldivmod
t=sympy.Symbol('t')
m=25
d=json.load(open('data/family25.json'))
def lines(m):
    L=[(1,r) for r in range(m)]+[(5*s,1) for s in range(5)]
    return L
def red(e): 
    e%=m
    return e-m if e>m//2 else e
def tpoly(H):
    return sympy.Poly(sum(t**i for i in range(H.bit_length()) if H>>i&1),t,modulus=2)
psis={e:tpoly(_psi(e)) for e in range(3,60,2)}
def name(g):
    for e,p in psis.items():
        if p==g: return 'Psi%d'%e
    if g==sympy.Poly(t,t,modulus=2): return 't'
    return str(g.as_expr())
